scwin.screenId = "jldinf91010";

///////// 1. 변수 및 선언 영역 /////////

scwin.dom_forn_isu_tp_cd = $c.util.getComponent('dom_forn_isu_tp_cd');

scwin.id_reg_button = $c.util.getComponent('id_reg_button');


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_oldStkcertIsuTpContn_txt", fn: function(){ return ((dma_map.get("oldStkcertIsuTpContn") ?? (() => { throw new Error("unresolved:" + "map.oldStkcertIsuTpContn"); })()) !== ''); } }, { id: "if_fornSecuKindNm_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "if_fornSecuKindNm_2_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) === ''); } }, { id: "if_fornSecuKindNm_3_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) === '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "rd_group", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "cfiCdGroupList5" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("cfiCdGroupList5"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "cfiCdGroupList5" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("cfiCdGroupList5")))).length === 0)); } }, { id: "rd_group_2", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "cfiCdGroupList6" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("cfiCdGroupList6"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "cfiCdGroupList6" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("cfiCdGroupList6")))).length === 0)); } }, { id: "rd_stdCdApctTpCd", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "stdCdApctTpCdList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("stdCdApctTpCdList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "stdCdApctTpCdList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("stdCdApctTpCdList")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "(" + String(dma_map.get("isurCd")) + ") " + String(dma_map.get("comNm")); } },
        { childId: "__rb6", fn: function () { return String(dma_map.get("domFornStkcertTpNm")) + "주권"; } },
        { childId: "__rb10", fn: function () { return String(dma_map.get("fornSecuKindNm")) + "&nbsp;&nbsp;(발행일:" + String(dma_map.get("fornSecuIsuDate")) + ")"; } },
        { childId: "__rb12", fn: function () { return "발행일:" + String(dma_map.get("fornSecuIsuDate")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.checkRegData();
        $("#group_C").attr("disabled", true);
        $("#group_Y").attr("disabled", true);
        scwin.setCfi();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91010.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_Chk_form();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf91010.onpageload' });
    }
};


