/**
 * @method
 * @name scwin.checkRadio
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkRadio = function () {
    /* sdd-asis-lifecycle:begin checkRadio — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const checkRdArr = $('input[key=checkRd]');
    const leng = checkRdArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkRdArr[i]).val();
            const target = $(checkRdArr[i]).attr("target");
            const checkId = $('label[for*=' + target + ']:contains(' + vl + ')').attr("for");
            const tObj = $('#' + checkId);
            if (tObj.length > 0) {
                $('#' + checkId)[0].checked = true;
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
