/**
 * @method
 * @name scwin.setCfi
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setCfi = function () {
    /* sdd-asis-lifecycle:begin setCfi — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const map_cfi_cd = $c.util.getComponent('ipt_cfiCd').getValue();
    const substr_cfi_category = map_cfi_cd.substring(0, 1);
    const substr_cfi_group = map_cfi_cd.substring(1, 2);
    const substr_cfi_attr1 = map_cfi_cd.substring(2, 3);
    const substr_cfi_attr2 = map_cfi_cd.substring(3, 4);
    const substr_cfi_attr3 = map_cfi_cd.substring(4, 5);
    const substr_cfi_attr4 = map_cfi_cd.substring(5, 6);
    $c.util.getComponent('ipt_cfiCdCategory').setValue(substr_cfi_category);
    $('input[name=group][value="' + substr_cfi_group + '"]').attr("checked", true);
    scwin.chg_group($("#group_" + substr_cfi_group));
    $c.util.getComponent('slc_attr01').setValue(substr_cfi_attr1);
    $c.util.getComponent('slc_attr02').setValue(substr_cfi_attr2);
    $c.util.getComponent('slc_attr03').setValue(substr_cfi_attr3);
    $c.util.getComponent('slc_attr04').setValue(substr_cfi_attr4);
    scwin.chg_attr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chg_group
 * @author Inswave
 * @date 2026. 09. 29
 * @param item
 * @returns
 * @hidden N
*/
scwin.chg_group = function (item) {
    /* sdd-asis-lifecycle:begin chg_group — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const temp = $('input[name=group]:checked').val();
    $c.util.getComponent('ipt_productDiv').setValue("02");
    if (temp === 'S' || temp === 'C' || temp === 'Y' || temp === 'M') {
        $c.util.getComponent('ipt_cfiCdCategory').setValue("E");
    } else {
        if (temp === 'P' || temp === 'F') {
            $c.util.getComponent('ipt_cfiCdCategory').setValue("E");
        } else {
            if (temp === 'I' || temp === 'B' || temp === 'E') {
                $c.util.getComponent('ipt_cfiCdCategory').setValue("C");
            } else {
                if (temp === 'L') {
                    $c.util.getComponent('ipt_cfiCdCategory').setValue("E");
                }
            }
        }
    }
    getCfiCode("JLDINF91010");
    scwin.chg_attr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chg_attr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chg_attr = function () {
    /* sdd-asis-lifecycle:begin chg_attr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_cfiCd').setValue("");
    $c.util.getComponent('ipt_cfiCd').setValue(($c.util.getComponent("ipt_cfiCdCategory").getValue() || '') + $('input[name=group]:checked').val() + ($c.util.getComponent("slc_attr01").getValue() || '') + ($c.util.getComponent("slc_attr02").getValue() || '') + ($c.util.getComponent("slc_attr03").getValue() || '') + ($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdGroup').setValue($('input[name=group]:checked').val());
    $c.util.getComponent('ipt_cfiCdAttr1').setValue(($c.util.getComponent("slc_attr01").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr2').setValue(($c.util.getComponent("slc_attr02").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr3').setValue(($c.util.getComponent("slc_attr03").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr4').setValue(($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_fisnVal').setValue("");
    $c.util.getComponent('ipt_fisnMakeYn').setValue("N");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.makeFisn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.makeFisn = async function () {
    /* sdd-asis-lifecycle:begin fn_make_fisn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const com_attr_tp_cd = '' + dma_companyInfoVO.get("comAttrTpCd") + '';
    if (com_attr_tp_cd !== "5" && com_attr_tp_cd !== "7") {
        $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));
    }
    const thisForm = $('#JLDINF10000');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    const v_group = $('input[name=group]:checked').val();
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    if (v_group === 'S' || v_group === 'C' || v_group === 'Y' || v_group === 'M') {
        temp += "/Com Sh";
        if ($c.util.getComponent('slc_attr01').getValue() === "N") {
            temp += " NVTG";
        }
        if ($c.util.getComponent('slc_attr03').getValue() === "P") {
            temp += " PP";
        }
        if ($c.util.getComponent('slc_attr02').getValue() === "T") {
            temp += " Rstd";
        } else {
            if ($c.util.getComponent('slc_attr02').getValue() === "U") {
                temp += " Unrestr";
            }
        }
        if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
            temp += " " + "" + dma_map.get("par_amt") + "";
        } else {
            temp += " " + "" + dma_map.get("par_amt") + "";
        }
    } else {
        if (v_group === 'P' || v_group === 'F') {
            if ($('input[name=group]:checked').val() === "F") {
                temp += "/Cv";
            } else {
                temp += "/";
            }
            temp += " Pref";
        } else {
            if (v_group === 'I' || v_group === 'B' || v_group === 'E') {
                if ($('input[name=group]:checked').val() === "B") {
                    temp += "/CIV REIT";
                } else {
                    if ($('input[name=group]:checked').val() === "E") {
                        temp += "/CIV ETF";
                    } else {
                        if ($('input[name=group]:checked').val() === "I") {
                            temp += "/CIV";
                        }
                    }
                }
                if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
                    temp += " KRW";
                } else {
                    if ($c.util.getComponent('slc_currTpCd').getValue() === "2") {
                        temp += " USD";
                    } else {
                        if ($c.util.getComponent('slc_currTpCd').getValue() === "3") {
                            temp += " JPY";
                        } else {
                            if ($c.util.getComponent('slc_currTpCd').getValue() === "4") {
                                temp += " EUR";
                            } else {
                                if ($c.util.getComponent('slc_currTpCd').getValue() === "5") {
                                    temp += " CNY";
                                } else {
                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "6") {
                                        temp += " GBP";
                                    } else {
                                        if ($c.util.getComponent('slc_currTpCd').getValue() === "7") {
                                            temp += " HKD";
                                        } else {
                                            if ($c.util.getComponent('slc_currTpCd').getValue() === "8") {
                                                temp += " AUD";
                                            } else {
                                                if ($c.util.getComponent('slc_currTpCd').getValue() === "9") {
                                                    temp += " SGD";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if (v_group === 'L') {
                    temp += "/Ltd Pshp";
                    if ($c.util.getComponent('slc_attr03').getValue() === "O") {
                        temp += " Nl Pd";
                    } else {
                        if ($c.util.getComponent('slc_attr03').getValue() === "P") {
                            temp += " PP";
                        } else {
                            if ($c.util.getComponent('slc_attr03').getValue() === "F") {
                                temp += " FPd";
                            }
                        }
                    }
                    if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
                        temp += " KRW";
                    } else {
                        if ($c.util.getComponent('slc_currTpCd').getValue() === "2") {
                            temp += " USD";
                        } else {
                            if ($c.util.getComponent('slc_currTpCd').getValue() === "3") {
                                temp += " JPY";
                            } else {
                                if ($c.util.getComponent('slc_currTpCd').getValue() === "4") {
                                    temp += " EUR";
                                } else {
                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "5") {
                                        temp += " CNY";
                                    } else {
                                        if ($c.util.getComponent('slc_currTpCd').getValue() === "6") {
                                            temp += " GBP";
                                        } else {
                                            if ($c.util.getComponent('slc_currTpCd').getValue() === "7") {
                                                temp += " HKD";
                                            } else {
                                                if ($c.util.getComponent('slc_currTpCd').getValue() === "8") {
                                                    temp += " AUD";
                                                } else {
                                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "9") {
                                                        temp += " SGD";
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (com_attr_tp_cd === "5" || com_attr_tp_cd === "7") {
        if ($c.util.getComponent('ipt_comEngAbbrv').getValue().length > 27) {
            temp = fn_cut_spacingWords(temp, 35);
        }
    }
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
    /* sdd-asis-lifecycle:end */
};


